{"code": "from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/data/workbook.xlsx'
wb=load_workbook(path, data_only=False)
print('Sheet names:', wb.sheetnames)
ws=wb['Task'] if 'Task' in wb.sheetnames else wb[wb.sheetnames[0]]
print('\nTask sheet:', ws.title)
print('Column D rows 12-31 (series codes):')
for r in range(12,32):
    print(f'D{r}={ws.cell(r,4).value!r}')
print('\nRow 10 columns H-L (years):')
for c in range(8,13):
    print(f'{get_column_letter(c)}10={ws.cell(10,c).value!r}')
print('\nRows 35-40 column D (region names for Net reliability gap):')
for r in range(35,41):
    print(f'D{r}={ws.cell(r,4).value!r}')
print('\nRows 42-47 column D (stat labels):')
for r in range(42,48):
    print(f'D{r}={ws.cell(r,4).value!r}')
print('\nRow 50 column D:')
print(f'D50={ws.cell(50,4).value!r}')

# Data sheet inspect
wdata=wb['Data'] if 'Data' in wb.sheetnames else wb[wb.sheetnames[1]]
print('\nData sheet:', wdata.title, 'max_row', wdata.max_row, 'max_col', wdata.max_column)
print('Data row 1:')
for c in range(1, wdata.max_column+1):
    v=wdata.cell(1,c).value
    if v is not None:
        print(f'{get_column_letter(c)}1={v!r}')
print('\nData rows 21-38 non-empty cells:')
for r in range(21,39):
    vals=[]
    for c in range(1, wdata.max_column+1):
        v=wdata.cell(r,c).value
        if v is not None:
            vals.append(f'{get_column_letter(c)}{r}={v!r}')
    print(' | '.join(vals))

print('\nPotential year header rows (rows 1-25, cols with 2010-2030-ish values):')
for r in range(1,26):
    vals=[]
    for c in range(1,wdata.max_column+1):
        v=wdata.cell(r,c).value
        if isinstance(v, int) and 1900 <= v <= 2100 or (isinstance(v,str) and v.isdigit() and 1900<=int(v)<=2100):
            vals.append(f'{get_column_letter(c)}{r}={v!r}')
    if vals:
        print(f'row {r}: ' + ', '.join(vals))"}

